.megasim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2733;
    background: linear-gradient(160deg, #eef1f5 0%, #e2e7ee 100%);
    border-radius: 18px;
}

.megasim-container * {
    box-sizing: border-box;
}

.megasim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #15233a 0%, #1f3a5f 55%, #2d567f 100%);
    color: #f3f6fa;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(21, 35, 58, 0.32);
    border-bottom: 4px solid #c79a3c;
}

.megasim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.megasim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e8c878;
    background: rgba(199, 154, 60, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.megasim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7e0ec;
}

.megasim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a4061;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.megasim-period-counter #currentDay,
.megasim-period-counter #maxPeriods {
    font-weight: 800;
    color: #15233a;
}

.megasim-round-name {
    background: #d4dded;
    color: #1f3a5f;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.megasim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3412;
    background: #fbe7da;
    padding: 4px 12px;
    border-radius: 999px;
}

.megasim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.megasim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6dde7;
    box-shadow: 0 4px 14px rgba(21, 35, 58, 0.06);
    border-top: 4px solid #2d567f;
}

.megasim-card-bcr { border-top-color: #1f7a55; }
.megasim-card-exposure { border-top-color: #9a3412; }
.megasim-card-float { border-top-color: #2d567f; }
.megasim-card-stakeholder { border-top-color: #c79a3c; }

.megasim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5d6f83;
}

.megasim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #15233a;
}

.megasim-card-bcr .megasim-value { color: #1f7a55; }
.megasim-card-exposure .megasim-value { color: #9a3412; }
.megasim-card-float .megasim-value { color: #2d567f; }
.megasim-card-stakeholder .megasim-value { color: #b9852b; }

.megasim-sublabel {
    font-size: 0.76rem;
    color: #6b7d90;
    line-height: 1.35;
}

.megasim-bcr-fail .megasim-value { color: #c0392b; }
.megasim-bcr-target .megasim-value { color: #1f7a55; }

.megasim-exposure-high .megasim-value { color: #c0392b; }
.megasim-exposure-low .megasim-value { color: #1f7a55; }

.megasim-float-low .megasim-value { color: #c0392b; }

.megasim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #15233a;
    color: #eaf0f7;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.megasim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e8c878;
}

.megasim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2d567f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(21, 35, 58, 0.05);
}

.megasim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.megasim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #15233a;
    margin-bottom: 6px;
}

.megasim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3e52;
}

.megasim-briefing-text strong { color: #1f7a55; }
.megasim-briefing-text em { color: #9a3412; font-style: italic; }

.megasim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6dde7;
    box-shadow: 0 4px 14px rgba(21, 35, 58, 0.06);
}

.megasim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #15233a;
    border-bottom: 2px solid #e2e7ee;
    padding-bottom: 8px;
}

.megasim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #233650;
    margin: 14px 0 6px;
}

.megasim-container select,
.megasim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b6c2d2;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f8fb;
    color: #1b2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.megasim-container select:focus,
.megasim-container input[type="number"]:focus {
    outline: none;
    border-color: #2d567f;
    box-shadow: 0 0 0 3px rgba(45, 86, 127, 0.16);
}

.megasim-container select option {
    background-color: #ffffff;
    color: #1b2733;
}

.megasim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2d567f;
}

.megasim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2d567f;
    margin-top: 4px;
}

.megasim-range-readout span:last-child {
    color: #1f7a55;
    font-weight: 800;
}

.megasim-hint {
    font-size: 0.8rem;
    color: #6b7d90;
    margin-top: 4px;
    line-height: 1.4;
}

.megasim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.megasim-container .btn-primary {
    background: linear-gradient(135deg, #1f3a5f 0%, #2d567f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 58, 95, 0.28);
}

.megasim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.megasim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b6c2d2;
    color: #5d6f83;
}

.megasim-coach {
    background: #15233a;
    color: #eaf0f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(21, 35, 58, 0.24);
    border-left: 5px solid #c79a3c;
}

.megasim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8c878;
    margin-bottom: 8px;
}

.megasim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.megasim-coach-body strong { color: #f0d28a; }
.megasim-coach-body em { color: #f3b48a; font-style: italic; }

.megasim-history,
.megasim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6dde7;
    box-shadow: 0 4px 14px rgba(21, 35, 58, 0.06);
}

.megasim-history h3,
.megasim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #15233a;
}

.megasim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #233650;
}

.megasim-container table#usfHistoryTable th {
    background: #e7ecf3;
    color: #15233a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2dbe7;
}

.megasim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f6;
}

.megasim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fc;
}

.megasim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .megasim-container {
        padding: 14px;
    }
    .megasim-header h1 {
        font-size: 1.7rem;
    }
    .megasim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .megasim-value {
        font-size: 1.9rem;
    }
    .megasim-clock {
        margin-left: 0;
    }
    .megasim-period-counter {
        font-size: 0.88rem;
    }
    .megasim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .megasim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, self-contained) ===== */
.megasim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #14243a; text-align: center; padding: 4px 2px 8px; }
.megasim-cm-title { font-size: 20px; font-weight: 700; color: #1c3a5e; margin-bottom: 14px; }
.megasim-cm-scorewrap { background: linear-gradient(135deg, #1c3a5e 0%, #2f6fb0 55%, #4aa3c7 100%); color: #f0f7fc; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.megasim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; }
.megasim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.85; }
.megasim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; }
.megasim-cm-badges { margin-top: 10px; }
.megasim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; }
.megasim-cm-badge-ok { background: #d3e9f7; color: #1c3a5e; }
.megasim-cm-badge-miss { background: #f7e2cf; color: #9a5a16; }
.megasim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 500px; }
.megasim-cm-kpi { flex: 1 1 105px; min-width: 105px; background: #eef4fa; border: 1px solid #d3e2f0; border-radius: 10px; padding: 10px 6px; }
.megasim-cm-kpi-val { font-size: 20px; font-weight: 700; color: #23507e; }
.megasim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #4a627a; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.megasim-cm-insights { text-align: left; max-width: 520px; margin: 0 auto; background: #f5f9fd; border-left: 4px solid #2f6fb0; border-radius: 8px; padding: 12px 16px; }
.megasim-cm-ins-h { font-weight: 700; color: #1c3a5e; margin-bottom: 6px; font-size: 14px; }
.megasim-cm-insights ul { margin: 0; padding-left: 18px; }
.megasim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #24384c; }
@media (max-width: 480px) { .megasim-cm-kpi { flex-basis: 40%; } .megasim-cm-score { font-size: 38px; } .megasim-cm-scorewrap { max-width: 100%; } }

