(function() {
    'use strict';

    class MegaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Owning the Megaproject`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` },
                { id: 5, titleKey: `briefing_title_r5`, textKey: `briefing_text_r5`, panelId: `round5Panel`, nameKey: `round_name_r5`, clockKey: `clock_r5` }
            ];

            // Numbers reference card (GBP).
            this.START_BCR = 1.30;          // Outline Business Case — marginal
            this.TARGET_BCR = 1.80;         // required to retain full funding
            this.FLOOR_BCR = 1.50;          // below → cut the £620M second station
            this.START_EXPOSURE = 2400;     // £M — unmitigated 50% overrun on £4.8bn
            this.START_FLOAT = 18;          // months of float to the 2034 opening
            this.START_STAKEHOLDER = 20;    // sponsor + supply-chain confidence (0–100)
            this.ENVELOPE = 4800;           // £M sanctioned budget
            this.SHOCK = 300;               // £M Round-5 tunnel cost shock
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    bcr: this.START_BCR,
                    exposure: this.START_EXPOSURE,
                    float: this.START_FLOAT,
                    stakeholder: this.START_STAKEHOLDER,
                    budgetUsed: 0,
                    stationCut: false,
                    riskDumped: false,
                    fundingPaused: false,
                    bcrHistory: [Math.round(this.START_BCR * 100)],
                    riskHistory: [this.START_EXPOSURE],
                    stakeholderHistory: [this.START_STAKEHOLDER],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            // Seed decisions to the NEUTRAL/middling DOM defaults — never the textbook-correct play.
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    role: `banker`,
                    weakness: `estimate`,
                    honesty: 50,
                    framing: `trim`,
                    station: `defer`,
                    benefits: 20,
                    rigour: 50,
                    model: `lumpsum`,
                    tunnel: `dump`,
                    incentive: 50,
                    premium: 400,
                    staging: `full`,
                    commit: 2400,
                    criteria: `schedule`,
                    optionality: 50,
                    governance: `committee`,
                    shock: `renegotiate`,
                    kpi: `costonly`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const getSel = (id, key) => { const el = document.getElementById(id); if (el) decisions[key] = el.value; };

            if (round === 1) {
                getSel(`roleInput`, `role`);
                getSel(`weaknessInput`, `weakness`);
                const hon = document.getElementById(`honestyInput`);
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                getSel(`framingInput`, `framing`);
                getSel(`stationInput`, `station`);
                const ben = document.getElementById(`benefitsInput`);
                const rig = document.getElementById(`rigourInput`);
                if (ben) decisions.benefits = parseFloat(ben.value);
                if (rig) decisions.rigour = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.benefits) || decisions.benefits < 0 || decisions.benefits > 120) {
                    warn(`warn_benefits_range`); return false;
                }
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 3) {
                getSel(`modelInput`, `model`);
                getSel(`tunnelInput`, `tunnel`);
                const inc = document.getElementById(`incentiveInput`);
                const prem = document.getElementById(`premiumInput`);
                if (inc) decisions.incentive = parseInt(inc.value, 10);
                if (prem) decisions.premium = parseFloat(prem.value);
                if (!Number.isFinite(decisions.incentive) || decisions.incentive < 0 || decisions.incentive > 100) {
                    warn(`warn_incentive_range`); return false;
                }
                if (!Number.isFinite(decisions.premium) || decisions.premium < 0 || decisions.premium > 1100) {
                    warn(`warn_premium_range`); return false;
                }
            } else if (round === 4) {
                getSel(`stagingInput`, `staging`);
                getSel(`criteriaInput`, `criteria`);
                const com = document.getElementById(`commitInput`);
                const opt = document.getElementById(`optionalityInput`);
                if (com) decisions.commit = parseFloat(com.value);
                if (opt) decisions.optionality = parseInt(opt.value, 10);
                if (!Number.isFinite(decisions.commit) || decisions.commit < 200 || decisions.commit > this.ENVELOPE) {
                    warn(`warn_commit_range`); return false;
                }
                if (!Number.isFinite(decisions.optionality) || decisions.optionality < 0 || decisions.optionality > 100) {
                    warn(`warn_optionality_range`); return false;
                }
            } else if (round === 5) {
                getSel(`governanceInput`, `governance`);
                getSel(`shockInput`, `shock`);
                getSel(`kpiInput`, `kpi`);
                const cv = document.getElementById(`convictionInput`);
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: bcr in hundredths; exposure in £M (negative delta = good); float in months;
            // stakeholder 0–100.
            let bcrDelta = 0, exposureDelta = 0, floatDelta = 0, stakeholderDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the owner's position: investor mindset, output-framing as the weakness.
                switch (d.role) {
                    case `investor`: stakeholderDelta += 8; bcrDelta += 4; coachKey = `coach_r1_investor`; break;
                    case `client`: stakeholderDelta -= 9; exposureDelta += 120; coachKey = `coach_r1_client`; break;
                    case `builder`: stakeholderDelta -= 6; floatDelta -= 1; coachKey = `coach_r1_builder`; break;
                    case `banker`: stakeholderDelta -= 4; coachKey = `coach_r1_banker`; break;
                }
                switch (d.weakness) {
                    case `proposition`: stakeholderDelta += 5; bcrDelta += 6; if (d.role === `investor`) coachKey = `coach_r1_diag_sharp`; break;
                    case `estimate`: bcrDelta -= 2; stakeholderDelta -= 6; coachKey = `coach_r1_estimate`; break;
                    case `optimism`: stakeholderDelta -= 4; coachKey = `coach_r1_optimism`; break;
                    case `politics`: stakeholderDelta -= 6; coachKey = `coach_r1_politics`; break;
                }
                if (d.honesty >= 60) { stakeholderDelta += 3; }
                else if (d.honesty <= 25) { stakeholderDelta -= 8; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.role === `investor` && d.weakness === `proposition`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Shape the value proposition — rebuild the BCR toward ≥1.80.
                switch (d.framing) {
                    case `outcomes`: bcrDelta += 30; stakeholderDelta += 6; coachKey = `coach_r2_outcomes`; break;
                    case `trim`: bcrDelta += 1; stakeholderDelta -= 8; coachKey = `coach_r2_trim`; break;
                    case `output`: bcrDelta -= 1; stakeholderDelta -= 4; coachKey = `coach_r2_output`; break;
                }
                // The second station drives ~40% of benefits.
                switch (d.station) {
                    case `keep`: bcrDelta += 14; stakeholderDelta += 4; if (d.framing === `outcomes`) coachKey = `coach_r2_keep`; break;
                    case `defer`: bcrDelta += 2; floatDelta += 1; coachKey = `coach_r2_defer`; break;
                    case `cut`: bcrDelta -= 18; stakeholderDelta -= 8; ds.stationCut = true; coachKey = `coach_r2_cut`; break;
                }
                // Benefits realization spend + a named owner make the BCR real after handover.
                spend += d.benefits;
                if (d.benefits >= 40) { bcrDelta += 8; stakeholderDelta += 3; }
                else if (d.benefits >= 15) { bcrDelta += 4; stakeholderDelta += 1; }
                else { stakeholderDelta -= 4; coachKey = `coach_r2_nobenefits`; }
                // Rigour: a defensible BCR vs an asserted one.
                if (d.rigour >= 60) { bcrDelta += 6; stakeholderDelta += 2; }
                else if (d.rigour <= 25) { bcrDelta -= 6; stakeholderDelta -= 4; coachKey = `coach_r2_lowrigour`; }

                summaryKey = (d.framing === `outcomes` && d.station === `keep`) ? `sum_r2_good` : (d.station === `cut` ? `sum_r2_cut` : `sum_r2_weak`);
            } else if (round === 3) {
                // Structure the delivery model + allocate the tunnel/junction risk.
                ds.riskDumped = false;
                switch (d.model) {
                    case `targetcost`: exposureDelta -= 320; stakeholderDelta += 6; coachKey = `coach_r3_targetcost`; break;
                    case `alliance`: exposureDelta -= 250; stakeholderDelta += 5; coachKey = `coach_r3_alliance`; break;
                    case `multipackage`: exposureDelta -= 280; stakeholderDelta += 4; coachKey = `coach_r3_multipackage`; break;
                    case `lumpsum`: exposureDelta += 320; stakeholderDelta -= 11; ds.riskDumped = true; coachKey = `coach_r3_lumpsum`; break;
                }
                // The two critical interfaces.
                switch (d.tunnel) {
                    case `shared`: exposureDelta -= 240; stakeholderDelta += 4; floatDelta += 1; if (d.model !== `lumpsum`) coachKey = `coach_r3_riskright`; break;
                    case `ownerall`: exposureDelta += 200; floatDelta -= 1; coachKey = `coach_r3_ownerall`; break;
                    case `dump`: exposureDelta += 280; stakeholderDelta -= 9; floatDelta -= 2; ds.riskDumped = true; coachKey = `coach_r3_dump`; break;
                }
                // Pain/gain incentive — an alliance without it just overruns together.
                if (d.incentive >= 60) {
                    exposureDelta -= 130; stakeholderDelta += 4;
                    if ((d.model === `alliance` || d.model === `targetcost`) && d.tunnel === `shared`) coachKey = `coach_r3_aligned`;
                } else if (d.incentive <= 25) {
                    exposureDelta += 130; stakeholderDelta -= 6;
                    if (d.model === `alliance` || d.model === `targetcost`) coachKey = `coach_r3_noincentive`;
                }
                // Risk premium: paying the supply chain to carry risk you cannot manage.
                spend += d.premium;
                if (d.model === `lumpsum` && d.premium < 700) { stakeholderDelta -= 8; coachKey = `coach_r3_underpremium`; }
                else if (d.premium >= 700) { exposureDelta += 60; }

                summaryKey = (d.model !== `lumpsum` && d.tunnel === `shared` && d.incentive >= 60) ? `sum_r3_good` : (d.model === `lumpsum` || d.tunnel === `dump` ? `sum_r3_dump` : `sum_r3_weak`);
            } else if (round === 4) {
                // Stage-gate the £4.8bn — preserve the option to stop, reprice, descope.
                switch (d.staging) {
                    case `gated`: exposureDelta -= 300; stakeholderDelta += 5; coachKey = `coach_r4_gated`; break;
                    case `twostep`: exposureDelta -= 110; stakeholderDelta += 2; coachKey = `coach_r4_twostep`; break;
                    case `full`: exposureDelta += 300; stakeholderDelta -= 11; coachKey = `coach_r4_full`; break;
                }
                ds.budgetUsed = Math.round(d.commit);
                // Lower early commitment preserves optionality and cuts exposure.
                const committedShare = d.commit / this.ENVELOPE;
                if (committedShare <= 0.4) { exposureDelta -= 200; }
                else if (committedShare <= 0.65) { exposureDelta -= 80; }
                else { exposureDelta += 220; if (d.staging === `gated`) coachKey = `coach_r4_overcommit`; }
                // Go/no-go criteria.
                switch (d.criteria) {
                    case `evidence`: exposureDelta -= 160; stakeholderDelta += 4; if (d.staging === `gated`) coachKey = `coach_r4_evidence`; break;
                    case `schedule`: exposureDelta += 60; coachKey = `coach_r4_schedule`; break;
                    case `none`: exposureDelta += 200; stakeholderDelta -= 8; coachKey = `coach_r4_nocriteria`; break;
                }
                // Preserved optionality (real-options value).
                if (d.optionality >= 60) { exposureDelta -= 130; stakeholderDelta += 3; }
                else if (d.optionality <= 25) { exposureDelta += 140; coachKey = `coach_r4_nooptionality`; }

                summaryKey = (d.staging === `gated` && d.criteria === `evidence` && committedShare <= 0.65) ? `sum_r4_good` : (d.staging === `full` ? `sum_r4_full` : `sum_r4_weak`);
            } else if (round === 5) {
                // Govern & defend — absorb the £300M tunnel shock through structure, not the balance sheet.
                switch (d.governance) {
                    case `defined`: stakeholderDelta += 5; exposureDelta -= 120; coachKey = `coach_r5_defined`; break;
                    case `committee`: stakeholderDelta -= 2; coachKey = `coach_r5_committee`; break;
                    case `crisis`: stakeholderDelta -= 12; exposureDelta += 160; coachKey = `coach_r5_crisis`; break;
                }
                // The live shock. A structure with shared risk + gates absorbs it; otherwise it lands public.
                const structured = !ds.riskDumped && d.governance === `defined`;
                switch (d.shock) {
                    case `absorb`:
                        if (structured) { stakeholderDelta += 5; exposureDelta -= 40; coachKey = `coach_r5_absorb`; }
                        else { exposureDelta += this.SHOCK * 0.7; stakeholderDelta += 1; coachKey = `coach_r5_absorb_weak`; }
                        break;
                    case `renegotiate`: exposureDelta += this.SHOCK * 0.6; floatDelta -= 2; stakeholderDelta -= 4; coachKey = `coach_r5_renegotiate`; break;
                    case `balancesheet`: exposureDelta += this.SHOCK; stakeholderDelta -= 14; coachKey = `coach_r5_balancesheet`; break;
                }
                // What you defend to the board.
                switch (d.kpi) {
                    case `fourkpi`: stakeholderDelta += 5; bcrDelta += 4; coachKey = (structured && d.shock === `absorb`) ? `coach_r5_fourkpi` : coachKey; break;
                    case `costonly`: stakeholderDelta -= 4; coachKey = `coach_r5_costonly`; break;
                    case `optimism`: stakeholderDelta -= 10; coachKey = `coach_r5_optimism`; break;
                }
                stakeholderDelta += Math.round((d.conviction - 60) / 15);

                summaryKey = (structured && d.shock === `absorb` && d.kpi === `fourkpi`) ? `sum_r5_good` : `sum_r5_weak`;
            }

            // Resource accounting (running capital committed; Round 4 sets it directly).
            if (round !== 4) ds.budgetUsed = Math.min(this.ENVELOPE, Math.round(ds.budgetUsed + spend));

            // Apply deltas with clamps that keep headroom so late-round levers still register.
            ds.bcr = Math.max(0.8, Math.min(2.6, ds.bcr + bcrDelta / 100));
            ds.exposure = Math.max(0, Math.min(3200, ds.exposure + exposureDelta));
            ds.float = Math.max(0, Math.min(24, ds.float + floatDelta));
            ds.stakeholder = Math.max(0, Math.min(100, ds.stakeholder + stakeholderDelta));

            // If the BCR drops below the floor, the second station is cut (loses its benefit driver).
            if (ds.bcr < this.FLOOR_BCR && !ds.stationCut && round >= 2) {
                ds.stationCut = true;
            }
            // Funding pause flag if the case never reaches the required BCR by the final board.
            if (round === this.ROUNDS.length && ds.bcr < this.TARGET_BCR) ds.fundingPaused = true;

            ds.bcrHistory.push(Math.round(ds.bcr * 100));
            ds.riskHistory.push(Math.round(ds.exposure));
            ds.stakeholderHistory.push(Math.round(ds.stakeholder));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite so express_resolveDomainScore (domainState.performance.overallScore) resolves.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                bcr: Math.round(ds.bcr * 100) / 100,
                bcrDelta: Math.round(bcrDelta) / 100,
                exposure: Math.round(ds.exposure),
                exposureDelta: Math.round(exposureDelta),
                float: Math.round(ds.float),
                stakeholder: Math.round(ds.stakeholder),
                stakeholderDelta: Math.round(stakeholderDelta),
                budgetUsed: ds.budgetUsed,
                stationCut: ds.stationCut,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

