        // v1.1.0: single source of truth for the composite (verbatim v1.0.0 formula).
        _composite(ds) {
            const bcr = Math.round(ds.bcr * 100) / 100;
            const exposure = Math.round(ds.exposure);
            const floatM = Math.round(ds.float);
            const stakeholder = Math.round(ds.stakeholder);
            const bcrScore = Math.max(0, Math.min(100, (bcr - 1.0) / 1.0 * 100));
            const exposureScore = Math.max(0, Math.min(100, (2400 - exposure) / 1700 * 100));
            const floatScore = Math.max(0, Math.min(100, floatM / 18 * 100));
            return Math.round(bcrScore * 0.30 + exposureScore * 0.30 + stakeholder * 0.25 + floatScore * 0.15);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const bcr = Math.round(ds.bcr * 100) / 100;
            const exposure = Math.round(ds.exposure);
            const floatM = Math.round(ds.float);
            const stakeholder = Math.round(ds.stakeholder);

            const hitBcr = bcr >= this.TARGET_BCR;
            const aboveFloor = bcr >= this.FLOOR_BCR;
            const lowExposure = exposure <= 900;
            // Composite components are scaled to the REACHABLE range so a textbook-correct owner
            // play clears the top tier with real headroom, not at the razor edge:
            //   BCR 1.00 → 0, 1.80 (target) → 80, ≥2.00 → 100 (best reachable ≈2.02).
            //   Exposure 2400 (unmitigated) → 0, ≤700 → 100 (best reachable ≈760).
            const bcrScore = Math.max(0, Math.min(100, (bcr - 1.0) / 1.0 * 100));
            const exposureScore = Math.max(0, Math.min(100, (2400 - exposure) / 1700 * 100));
            const floatScore = Math.max(0, Math.min(100, floatM / 18 * 100));
            const composite = this._composite(ds);

            let performance = `Funding Paused`, performanceKey = `grade_paused`;
            if (hitBcr && lowExposure && composite >= 80) { performance = `Owner-Investor — Funding Secured`; performanceKey = `grade_secured`; }
            else if (hitBcr && lowExposure) { performance = `Credible Owner Case`; performanceKey = `grade_credible`; }
            else if (hitBcr) { performance = `Funded but Over-Exposed`; performanceKey = `grade_overexposed`; }
            else if (aboveFloor) { performance = `Full Scheme Intact, Case Short`; performanceKey = `grade_caseshort`; }
            else { performance = `Second Station Cut`; performanceKey = `grade_stationcut`; }

            const insights = [];
            if (hitBcr && lowExposure) insights.push(window.mySimulation.t(`insight_secured`));
            else if (hitBcr) insights.push(window.mySimulation.t(`insight_exposed`));
            else if (aboveFloor) insights.push(window.mySimulation.t(`insight_short`));
            else insights.push(window.mySimulation.t(`insight_stationcut`));

            if (ds.stationCut) insights.push(window.mySimulation.t(`insight_lost40`));
            if (exposure >= 2000) insights.push(window.mySimulation.t(`insight_overrun`));
            if (stakeholder < 45) insights.push(window.mySimulation.t(`insight_lowtrust`));
            if (hitBcr && lowExposure && stakeholder >= 70) insights.push(window.mySimulation.t(`insight_governed`));

            return {
                bcr: bcr,
                exposure: exposure,
                float: floatM,
                stakeholder: stakeholder,
                hitBcr: hitBcr,
                met: (hitBcr && lowExposure),
                composite: composite,
                overallScore: composite,
                performance: performance,
                performanceKey: performanceKey,
                totalPeriods: history.length,
                insights: insights
            };
        }

        // v1.1.0: localized completion debrief (engine otherwise shows a generic fallback).
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.overallScore != null ? s.overallScore : 0);
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performance || '');
            const met = !!s.met;
            const badge = met
                ? `<span class="megasim-cm-badge megasim-cm-badge-ok">${t('cm_targets_met')}</span>`
                : `<span class="megasim-cm-badge megasim-cm-badge-miss">${t('cm_targets_missed')}</span>`;
            const kpi = (k, v, suf) => `<div class="megasim-cm-kpi"><div class="megasim-cm-kpi-val">${(v != null ? v : '—')}${suf || ''}</div><div class="megasim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="megasim-cm-insights"><div class="megasim-cm-ins-h">${t('cm_insights')}</div><ul>${ins.map((i) => `<li>${i}</li>`).join('')}</ul></div>`
                : '';
            return `
                <div class="megasim-cm">
                    <div class="megasim-cm-title">${t('cm_title')}</div>
                    <div class="megasim-cm-scorewrap">
                        <div class="megasim-cm-score">${score}<span class="megasim-cm-score-max">/100</span></div>
                        <div class="megasim-cm-grade">${grade}</div>
                        <div class="megasim-cm-badges">${badge}</div>
                    </div>
                    <div class="megasim-cm-kpis">
                        ${kpi('cm_kpi_bcr', (s.bcr != null ? s.bcr.toFixed(2) : null), '')}
                        ${kpi('cm_kpi_exposure', s.exposure, ' £M')}
                        ${kpi('cm_kpi_float', s.float, ' mo')}
                        ${kpi('cm_kpi_stakeholder', s.stakeholder, '')}
                    </div>
                    ${insHtml}
                </div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.stationCut) return window.mySimulation.t(`hint_stationcut`);
            if (ds.riskDumped && state.currentPeriod >= 3) return window.mySimulation.t(`hint_riskdump`);
            if (ds.exposure >= 2200 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_exposure`);
            if (ds.bcr < this.FLOOR_BCR && state.currentPeriod >= 2) return window.mySimulation.t(`hint_bcr`);
            if (ds.bcr >= this.TARGET_BCR && ds.exposure <= 900 && ds.stakeholder >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

